import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine()); StringBuilder sb = new StringBuilder(); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); String a = br.readLine(); String b = br.readLine(); int chefScore = 0; int chefinaScore = 0; int losses = 0; int draws = 0; for (int i = 0; i < n; i++) { char c = a.charAt(i); char f = b.charAt(i); if (c == f) { draws++; } else if ((c == 'R' && f == 'S') || (c == 'S' && f == 'P') || (c == 'P' && f == 'R')) { chefScore++; } else { chefinaScore++; losses++; } } int changes = 0; while (chefScore <= chefinaScore) { if (losses > 0) { chefScore++; chefinaScore--; losses--; } else { chefScore++; draws--; } changes++; } sb.append(changes).append("\n"); } System.out.print(sb); } }